from pathlib import Path
import os,json,hashlib
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[2];O=R/'qa/hit-body';O.mkdir(exist_ok=True);html=(R/'dist/INK-Street-Fighter-6.html').read_bytes();rows=[]
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path=os.environ['INK_CHROMIUM'],headless=True);p=b.new_page(viewport={'width':1440,'height':1000});errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html.decode());p.wait_for_function('window.INKDuel?.ready');p.locator('.kinetic-launch button').click()
 for char,move in [('cammy','sMP'),('luke','cMK'),('mai','sHP')]:
  initial=p.evaluate('''([char,move])=>{const A=SVG_FIGHTER,G=A.state;A.start('ryu',char,'training','classic',42);G.paused=true;document.getElementById('dummy').value='idle';A.teleport(0,560);A.teleport(1,760);G.paused=false;const accepted=A.tryMove(0,move);G.paused=true;const f=A.fighters[1];for(let i=0;i<60&&!f._inkHitBody?.length;i++)A.step();const r=f._inkReaction,before=JSON.stringify(A.combatState()),pose=JSON.stringify(A.visualPose(f)),clock=f._inkVisualClock;for(let i=0;i<6;i++)A.renderFraction(i%3/2);const pure=before===JSON.stringify(A.combatState())&&pose===JSON.stringify(A.visualPose(f));let frozen=true;if(G.hitstop>1){A.step();frozen=clock===f._inkVisualClock;}window.hitBorn=r?.actorBirth;return {accepted,hit:!!f._inkHitBody?.length,hurtPart:r?.contact?.hurtPart,zone:r?.zone,point:r?.contact?.point,pure,frozen};}''',[char,move]);samples=[]
  for age in [0,3,6,10]:
   sample=p.evaluate('''age=>{const A=SVG_FIGHTER,f=A.fighters[1];for(let i=0;i<90&&f._inkVisualClock-window.hitBorn<age;i++)A.step();const pose=A.visualPose(f),frame=INK.VisualFrame.get(pose);A.renderFraction(1);return {age:f._inkVisualClock-window.hitBorn,state:f.state,delta:INK.HitBody.sample(f,f._inkVisualClock),feet:frame?.worldFeet};}''',age);samples.append(sample);p.locator('#game').screenshot(path=str(O/(char+'-'+str(age)+'.png')))
  follow=p.evaluate('''()=>{const A=SVG_FIGHTER,G=A.state,f=A.fighters[1];for(let i=0;i<100&&f.state!=='idle';i++)A.step();G.paused=false;const accepted=A.tryMove(1,'sLP');G.paused=true;A.step();const source={fw:[1,2],rw:[3,4],fa:[5,6],ra:[7,8]},before=JSON.stringify(source);INK.HitBody.response(f,source,f._inkReaction,f._inkVisualClock);return {accepted,attack:!!f.attack,unchanged:before===JSON.stringify(source)};}''');rows.append({'character':char,'move':move,'initial':initial,'samples':samples,'follow':follow})
 b.close()
report={'htmlSha256':hashlib.sha256(html).hexdigest(),'rows':rows,'errors':errors};(O/'playable.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps([{k:v for k,v in r.items() if k!='samples'} for r in rows],indent=2));assert not errors and all(r['initial']['hit'] and r['initial']['pure'] and r['initial']['frozen'] and all(r['follow'].values()) for r in rows)
